content.css:
.growthStackedChart {
  width: 100%;
  height: 100%;
}
.growthStackedChart svg {
  width: 100%;
  height: 100%;
  font-family: "Segoe UI", "Helvetica Neue", Arial, sans-serif;
}
.growthStackedChart .axis {
  font-size: 11px;
  color: #666;
}
.growthStackedChart .axis path,
.growthStackedChart .axis line {
  fill: none;
  stroke: #ccc;
  shape-rendering: crispEdges;
}
.growthStackedChart .axis text {
  fill: #666;
}
.growthStackedChart .axis-label {
  font-size: 13px;
  font-weight: 600;
  fill: #333;
}
.growthStackedChart .grid-line {
  stroke: #e8e8e8;
  stroke-dasharray: 3, 3;
  stroke-width: 1;
}
.growthStackedChart .bar-rect {
  stroke: #fff;
  stroke-width: 1;
  cursor: pointer;
  transition: opacity 0.15s ease;
}
.growthStackedChart .bar-rect:hover {
  opacity: 0.85;
  stroke: #333;
  stroke-width: 1.5;
}
.growthStackedChart .bar-rect:focus {
  outline: 2px solid #1f6fd4;
  outline-offset: 1px;
  stroke: #333;
  stroke-width: 1.5;
}
.growthStackedChart .segment-label {
  font-size: 10px;
  fill: #fff;
  text-anchor: middle;
  pointer-events: none;
  font-weight: 500;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
}
.growthStackedChart .segment-label-dark {
  fill: #333;
  text-shadow: none;
}
.growthStackedChart .total-label {
  font-size: 12px;
  font-weight: 700;
  fill: #333;
  text-anchor: middle;
}
.growthStackedChart .growth-label {
  font-size: 14px;
  font-weight: 700;
  text-anchor: middle;
}
.growthStackedChart .growth-line {
  stroke-width: 2;
  stroke-dasharray: 4, 3;
  fill: none;
}
.growthStackedChart .year-label {
  font-size: 11px;
  fill: #555;
  text-anchor: middle;
  font-weight: 600;
}
.growthStackedChart .legend-item {
  cursor: pointer;
}
.growthStackedChart .legend-item text {
  font-size: 11px;
  fill: #555;
}
.growthStackedChart .legend-item rect {
  rx: 2;
  ry: 2;
}
